package com.fream.back.domain.style.controller.command;

import com.fream.back.domain.style.dto.InstantStyleRequestDto;
import com.fream.back.domain.style.dto.StyleBidRequestDto;
import com.fream.back.domain.style.service.command.StyleBidCommandService;
import com.fream.back.global.utils.SecurityUtils;
import lombok.RequiredArgsConstructor;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/sale-bids")
@RequiredArgsConstructor
public class StyleBidCommandController {

    private final StyleBidCommandService saleBidCommandService;


    @PostMapping
    public ResponseEntity<Long> createSaleBid(
            @RequestBody StyleBidRequestDto requestDto) {
        String email = SecurityUtils.extractEmailFromSecurityContext();
        Long saleBidId = saleBidCommandService.createSaleBid(
                email,
                requestDto.getProductSizeId(),
                requestDto.getBidPrice(),
                requestDto.getReturnAddress(),
                requestDto.getPostalCode(),
                requestDto.getReceiverPhone(),
                requestDto.isWarehouseStorage()
        ).getId();
        return ResponseEntity.ok(saleBidId);
    }


    @DeleteMapping("/{saleBidId}")
    public ResponseEntity<Void> deleteSaleBid(
            @PathVariable("saleBidId") Long saleBidId) {
        saleBidCommandService.deleteSaleBid(saleBidId);
        return ResponseEntity.ok().build();
    }

    @PostMapping("/instant")
    public ResponseEntity<Long> createInstantSale(
            @RequestBody InstantStyleRequestDto requestDto) {
        String sellerEmail = SecurityUtils.extractEmailFromSecurityContext();
        Long saleId = saleBidCommandService.createInstantSaleBid(
                requestDto.getOrderBidId(),
                sellerEmail,
                requestDto.getReturnAddress(),
                requestDto.getPostalCode(),
                requestDto.getReceiverPhone()
        );
        return ResponseEntity.ok(saleId);
    }
}

package com.fream.back.domain.style.controller.command;

import com.fream.back.domain.style.dto.AddressRequestDto;
import com.fream.back.domain.style.service.command.StyleCommandService;
import lombok.RequiredArgsConstructor;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/sales")
@RequiredArgsConstructor
public class StyleCommandController {

    private final StyleCommandService saleCommandService;



    @PostMapping("/{saleId}/shipment")
    public ResponseEntity<Void> createSellerShipment(
            @PathVariable("saleId") Long saleId,
            @RequestBody AddressRequestDto requestDto
    ) {
        saleCommandService.createSellerShipment(
                saleId,
                requestDto.getCourier(),
                requestDto.getTrackingNumber()
        );
        return ResponseEntity.ok().build();
    }
}

