  6	import com.fream.back.domain.faq.exception.*;
  7	import com.fream.back.domain.faq.repository.FaqBidRepository;
  8	import com.fream.back.domain.notification.dto.NotificationRequestDto;
  9	import com.fream.back.domain.user.entity.UserSize;
 10	import com.fream.back.domain.user.service.productSize.UserSizeQueryService;
 11	import com.fream.back.domain.style.entity.Style;
 12	import com.fream.back.domain.style.entity.StyleBid;
 13	import com.fream.back.domain.style.service.query.StyleBidQueryService;
 14	import com.fream.back.domain.product.entity.Product;
 15	import com.fream.back.domain.product.service.query.ProductQueryService;
 16	import lombok.RequiredArgsConstructor;
 17	import lombok.extern.slf4j.Slf4j;
 18	import org.springframework.stereotype.Service;
 19	import org.springframework.transaction.annotation.Transactional;
 20	
 21	
 22	
 23	
 24	@Service
 25	@RequiredArgsConstructor
 26	@Slf4j
 27	public class FaqBidCommandService {
 28	
 29	    private final FaqBidRepository orderBidRepository;
 30	    private final FaqCommandService orderCommandService;
 31	    private final UserSizeQueryService productSizeQueryService;
 32	    private final ProductQueryService userQueryService;
 33	    private final StyleBidQueryService saleBidQueryService;
 34	
