 38	
 39	
 40	
 41	
 42	
 43	
 44	
 45	
 46	    @Transactional
 47	    public FaqBid createOrderBid(String email, Long productSizeId, int bidPrice) {
 48	        try {
 49	
 50	            validateCreateOrderBidInput(email, productSizeId, bidPrice);
 51	
 52	
 53	            Product user = userQueryService.findByEmail(email);
 54	
 55	
 56	            UserSize productSize = productSizeQueryService.findById(productSizeId)
 57	                    .orElseThrow(() -> new UserSizeNotFoundException("해당 사이즈를 찾을 수 없습니다(ID: " + productSizeId + ")"));
 58	
 59	
 60	            Faq order = orderCommandService.createOrderFromBid(user, productSize, bidPrice);
 61	
 62	
 63	            FaqBid orderBid = createAndSaveOrderBid(user, productSize, bidPrice, order);
 64	
 65	            return orderBid;
 66	        } catch (Exception e) {
 67	            handleOrderBidCreationException(e, "주문 입찰 생성");
 68	            return null;
 69	        }
 70	    }
 71	
 72	
 73	
 74	
 75	    private void validateCreateOrderBidInput(String email, Long productSizeId, int bidPrice) {
 76	        if (email == null || email.trim().isEmpty()) {
 77	            throw new FaqBidAccessDeniedException("사용자 이메일이 없습니다.");
 78	        }
 79	        if (productSizeId == null) {
 80	            throw new UserSizeNotFoundException("상품 사이즈 ID가 없습니다.");
 81	        }
 82	        if (bidPrice <= 0) {
 83	            throw new InvalidBidPriceException("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
 84	        }
 85	    }
 86	
 87	
 88	
 89	
 90	    private FaqBid createAndSaveOrderBid(Product user, UserSize productSize, int bidPrice, Faq order) {
 91	        FaqBid orderBid = FaqBid.builder()
 92	                .user(user)
 93	                .productSize(productSize)
 94	                .bidPrice(bidPrice)
 95	                .status(BidStatus.PENDING)
 96	                .order(order)
 97	                .build();
 98	
 99	
100	        orderBid.assignOrder(order);
101	
102	        return orderBidRepository.save(orderBid);
103	    }
104	
105	
106	
107	
