114	
115	
116	
117	
118	    @Transactional
119	    public FaqBid createInstantOrderBid(String buyerEmail, Long saleBidId, Long addressId,
120	                                          boolean isWarehouseStorage, NotificationRequestDto paymentRequest) {
121	        try {
122	
123	            validateInstantOrderBidInput(buyerEmail, saleBidId, addressId, paymentRequest);
124	
125	
126	            Product buyer = userQueryService.findByEmail(buyerEmail);
127	
128	
129	            StyleBid saleBid = getSaleBidAndValidate(saleBidId);
130	            Style sale = saleBid.getSale();
131	
132	
133	            Faq order = orderCommandService.createInstantOrder(
134	                    buyer,
135	                    saleBid,
136	                    addressId,
137	                    isWarehouseStorage,
138	                    paymentRequest
139	            );
140	
141	
142	            FaqBid orderBid = createInstantOrderBid(order, saleBid, sale);
143	
144	            return orderBid;
145	        } catch (Exception e) {
146	            handleOrderBidCreationException(e, "즉시 구매 주문 입찰 생성");
147	            return null;
148	        }
149	    }
150	
151	
152	
153	
154	    private void validateInstantOrderBidInput(String buyerEmail, Long saleBidId, Long addressId, NotificationRequestDto paymentRequest) {
155	        if (buyerEmail == null || buyerEmail.trim().isEmpty()) {
156	            throw new FaqBidAccessDeniedException("구매자 이메일이 없습니다.");
157	        }
158	        if (saleBidId == null) {
159	            throw new StyleBidNotFoundException("판매 입찰 ID가 없습니다.");
160	        }
161	        if (addressId == null) {
162	            throw new InvalidFaqBidDataException("배송지 ID가 없습니다.");
163	        }
164	        if (paymentRequest == null) {
165	            throw new InvalidNotificationAddressDataException("결제 정보가 없습니다.");
166	        }
167	    }
168	
169	
170	
171	
172	    private StyleBid getSaleBidAndValidate(Long saleBidId) {
173	        StyleBid saleBid = saleBidQueryService.findById(saleBidId);
174	        if (saleBid == null) {
175	            throw new StyleBidNotFoundException("판매 입찰을 찾을 수 없습니다(ID: " + saleBidId + ")");
176	        }
177	
178	        Style sale = saleBid.getSale();
179	        if (sale == null) {
180	            throw new InvalidFaqBidDataException("판매 입찰과 연결된 판매 정보가 없습니다.");
181	        }
182	
183	        return saleBid;
184	    }
185	
186	
187	
188	
189	    private FaqBid createInstantOrderBid(Faq order, StyleBid saleBid, Style sale) {
190	        UserSize productSize = saleBid.getProductSize();
191	
192	        FaqBid orderBid = FaqBid.builder()
193	                .user(order.getUser())
194	                .productSize(productSize)
195	                .bidPrice(saleBid.getBidPrice())
196	                .status(BidStatus.MATCHED)
197	                .order(order)
198	                .sale(sale)
199	                .build();
200	
201	
202	        orderBid.assignOrder(order);
203	
204	
205	        orderBid.markAsInstantPurchase();
206	        return orderBidRepository.save(orderBid);
207	    }
208	
