212	    private void handleOrderBidCreationException(Exception e, String operation) {
213	        if (e instanceof FaqException) {
214	            throw (FaqException) e;
215	        }
216	        log.error("{} 중 오류 발생: {}", operation, e.getMessage(), e);
217	        throw new FaqBidCreationFailedException(operation + " 중 오류가 발생했습니다: " + e.getMessage(), e);
218	    }
