   603	    private void sendRefundNotification(Notification payment) {
   604	        try {
   605	            Product user = payment.getUser();
   606	            if (user == null) {
   607	                log.warn("환불 알림 발송 실패: 결제ID={}, 사용자 정보가 없습니다.", payment.getId());
   608	                return;
   609	            }
   611	            Faq order = payment.getOrder();
   612	            String orderInfo = order != null ? "주문 ID: " + order.getId() : "환불금액: " + payment.getPaidAmount() + "원";
   614	            notificationCommandService.createNotification(
   615	                    user.getId(),
   616	                    PaymentCategory.SHOPPING,
   617	                    PaymentType.REFUND,
   618	                    "결제가 환불되었습니다. " + orderInfo
   619	            );
   620	            log.debug("환불 알림 전송 완료: 사용자ID={}, 결제ID={}", user.getId(), payment.getId());
   623	            if (order != null) {
   624	                Style sale = null;
   627	                FaqBid orderBid = order.getOrderBid();
   628	                if (orderBid != null) {
   629	                    sale = orderBid.getSale();
   630	                }
   632	                else {
   633	                    StyleBid saleBid = saleBidQueryService.findByOrderId(order.getId());
   634	                    if (saleBid != null) {
   635	                        sale = saleBid.getSale();
   636	                    }
   637	                }
   639	                if (sale != null && sale.getSeller() != null) {
   640	                    Product seller = sale.getSeller();
   641	                    notificationCommandService.createNotification(
   642	                            seller.getId(),
   643	                            PaymentCategory.SHOPPING,
   644	                            PaymentType.REFUND,
