   560	                throw new NotificationException(NotificationErrorCode.PAYMENT_CANCELLATION_FAILED,
   561	                        "환불 가능한 결제 ID가 없습니다.");
   562	            }
   564	            boolean refundSuccess = portOneApiClient.cancelPayment(payment.getImpUid());
   566	            if (refundSuccess) {
   567	                payment.updateStatus(NotificationStatus.REFUNDED);
