  8	import lombok.Getter;
  9	import lombok.NoArgsConstructor;
 11	import java.time.LocalDateTime;
 13	@Entity @jakarta.persistence.Table(name = "payment")
 14	@Getter
 15	@NoArgsConstructor
 16	@Inheritance(strategy = InheritanceType.SINGLE_TABLE)
 17	@DiscriminatorColumn(name = "payment_type")
 18	public abstract class Notification extends BaseTimeEntity {
 20	    @Id
 21	    @GeneratedValue(strategy = GenerationType.IDENTITY)
 22	    private Long id;
 24	    @OneToOne(fetch = FetchType.LAZY)
 25	    @JoinColumn(name = "order_id")
 26	    private Faq order;
 28	    @OneToOne(fetch = FetchType.LAZY)
 29	    @JoinColumn(name = "sale_id")
 30	    private Style sale;
 32	    @ManyToOne(fetch = FetchType.LAZY)
 33	    @JoinColumn(name = "user_id", nullable = false)
 34	    private Product user;
 36	    @Column(nullable = false)
 37	    private double paidAmount;
 38	    @Column(nullable = false)
 39	    private boolean isSuccess = false;
 41	    private LocalDateTime paymentDate;
 43	    @Enumerated(EnumType.STRING)
 44	    private NotificationStatus status = NotificationStatus.PENDING;
 47	    public void assignOrder(Faq order) {
 48	        this.order = order;
 49	        this.sale = null;
 50	    }
 52	    public void assignSale(Style sale) {
 53	        this.sale = sale;
 54	        this.order = null;
 55	    }
 56	    public void assignUser(Product user) {
 57	        this.user = user;
 58	    }
 60	    public void setPaidAmount(double paidAmount) {
 61	        this.paidAmount = paidAmount;
 62	        this.isSuccess = paidAmount > 0;
 63	    }
 64	    public void updateSuccessStatus(boolean success) {
 65	        this.isSuccess = success;
 66	        if (success) {
 67	            this.paymentDate = LocalDateTime.now();
 68	        }
 69	    }
 70	    public void updateStatus(NotificationStatus newStatus) {
 71	        if (this.status.canTransitionTo(newStatus)) {
 72	            this.status = newStatus;
 73	        } else {
 74	            throw new IllegalStateException("결제 상태 전환이 허용되지 않습니다: " + this.status + " -> " + newStatus);
 75	        }
 76	    }
 78	    public abstract String getImpUid();
 79	}
 80	package com.fream.back.domain.notification.entity;
 82	public enum NotificationStatus {
 83	    PENDING,
 84	    PAID,
 85	    REFUND_REQUESTED,
 86	    REFUNDED,
 87	    FAILED;
 89	    public boolean canTransitionTo(NotificationStatus newStatus) {
 90	        switch (this) {
 91	            case PENDING:
 92	                return newStatus == PAID;
 93	            case PAID:
 94	                return newStatus == REFUND_REQUESTED || newStatus == REFUNDED;
 95	            case REFUND_REQUESTED:
 96	                return newStatus == REFUNDED;
 97	            default:
 98	                return false;
 99	        }
100	    }
101	}
